-- Departamentos con subcategorías, marca y precio anterior, y el surtido de supermercado.
-- Las marcas son genéricas. El stock de cada sede sigue la misma regla que el catálogo original.
ALTER TABLE products ADD COLUMN subcategory VARCHAR(60);
ALTER TABLE products ADD COLUMN brand VARCHAR(40);
ALTER TABLE products ADD COLUMN list_price NUMERIC(10, 2);

