-- Inventario de las tres sedes para los productos nuevos (los exclusivos de sede no se tocan).
SELECT t.id,
       p.id,
       CASE WHEN (p.id * 13 + t.id) % 41 = 0 THEN 1
            ELSE GREATEST(3, p.initial_stock + ((p.id * 7 + t.id * 3) % 9) - 4) END,
       GREATEST(2, p.initial_stock / 4),
       GREATEST(4, p.initial_stock)
FROM tiendas t
CROSS JOIN products p
WHERE NOT EXISTS (SELECT 1 FROM inventario i WHERE i.producto_id = p.id);

UPDATE products p SET stock = COALESCE((SELECT SUM(i.stock) FROM inventario i WHERE i.producto_id = p.id), 0)
WHERE p.subcategory IS NOT NULL AND p.brand IS NOT NULL;
